#include <xc.h> // compilateur
#include <stdbool.h>  // standard bool
#include <stdint.h> // standard ints

#include "LCD.h"

//----- Constant Definiton  ----------------------------
#define LCD_RS LATAbits.LATA6 // RA6 -> RS
#define LCD_RW LATAbits.LATA5 // RA5 -> R/W
#define LCD_E LATAbits.LATA4 // RA4 -> E  

#define LCD_BACKLIGHT LATAbits.LATA7 // RA7 -> BL    

#define LCD_MODE_CMD 0 // mode instruction (RS)
#define LCD_MODE_DATA 1 // mode data

#define LCD_WRITE 0 // ecriture
#define LCD_READ 1 // lecture

#define LCD_DATA_R PORTA // lecture donnee portA
#define LCD_DATA_W LATA // ecriture donnee latA

#define LCD_HIGH 1 // etat haut
#define LCD_LOW 0 // etat bas

#define LCD_COMMAND_FUNCTION_SET 0b00101000 // (- - - - N F 0 0)
// Display line number control bit
// When N = "Low", it means 1-line display mode.
// When N = "High", 2-line display mode is set. <-
// F : Display font type control bit
// When F = "Low", it means 5 x 8 dots format display mode <-
// When F = "High", 5 x 11 dots format display mode.

#define LCD_COMMAND_DISPLAY_OFF 0b00001000

#define LCD_COMMAND_DISPLAY_CLEAR 0b00000001

#define LCD_COMMAND_ENTRY_MODE_SET 0b00000110   // (- - - - 0 1 I/D S)
// I/D : Increment / decrement of DDRAM address (cursor or blink)
// When I/D = "High", cursor/blink moves to right and DDRAM address is increased by 1.
// When I/D = "Low", cursor/blink moves to left and DDRAM address is decreased by 1.
// * CGRAM operates the same as DDRAM, when read from or write to CGRAM.
// S: Shift of entire display
// When DDRAM read (CGRAM read/write) operation or S = "Low", shift of entire display is not performed. If S =
// "High" and DDRAM write operation, shift of entire display is performed according to I/D value (I/D = "1" : shift
// left, I/D = "0" : shift right).

// S I/D   DESCRIPTION
// H  H    Shift the display to the left 
// H  L    Shift the display to the right <- 

#define LCD_COMMAND_DISPLAY_ON 0b00001100   // (- - - - 1 D C B)
// D : Display ON/OFF control bit
// When D = "High", entire display is turned on. <-
// When D = "Low", display is turned off, but display data is remained in DDRAM.
// C : Cursor ON/OFF control bit
// When C = "High", cursor is turned on. <-
// When C = "Low", cursor is disappeared in current display, but I/D register remains its data.
// B : Cursor Blink ON/OFF control bit
// When B = "High", cursor blink is on, that performs alternate between all the high data and display character at
// the cursor position. <-
// When B = "Low", blink is off.

#define LCD_COMMAND_CURSOR_ON 0b00001101    // (1 D C B)
// D : Display ON/OFF control bit
// When D = "High", entire display is turned on. <-
// When D = "Low", display is turned off, but display data is remained in DDRAM.
// C : Cursor ON/OFF control bit
// When C = "High", cursor is turned on. 
// When C = "Low", cursor is disappeared in current display, but I/D register remains its data. <-
// B : Cursor Blink ON/OFF control bit
// When B = "High", cursor blink is on, that performs alternate between all the high data and display character at
// the cursor position. <-
// When B = "Low", blink is off.

#define LCD_COMMAND_CURSOR_OFF 0b00001100   // (1 D C B)
// D : Display ON/OFF control bit
// When D = "High", entire display is turned on. <-
// When D = "Low", display is turned off, but display data is remained in DDRAM.
// C : Cursor ON/OFF control bit
// When C = "High", cursor is turned on. 
// When C = "Low", cursor is disappeared in current display, but I/D register remains its data. <-
// B : Cursor Blink ON/OFF control bit
// When B = "High", cursor blink is on, that performs alternate between all the high data and display character at
// the cursor position. <-
// When B = "Low", blink is off.

#define _XTAL_FREQ 32000000 // 32Mhz freq pour delay

