// Sous programme LCD_Init
// Auteur: Rolle Clement
// Desc.: sous programme d'initialisation du LCD
// Ver. Date: V00 20231222 Cr�ation (YYYYMMDD)	
//---------------------------------------------------------

void LCD_Init(void)
{
    // cf datasheet st7066 p.20 -> initialisation 4bits interface

    __delay_ms(16); // Wait time > 15ms -> Power On LCD

    LCD_RW = LCD_WRITE;
    LCD_RS = LCD_MODE_CMD;

    LCD_Write_Quartet(0b0011);

    __delay_ms(5); // Wait time > 4.1ms

    LCD_Write_Quartet(0b0011);

    __delay_us(110); // Wait time > 100us

    LCD_Write_Quartet(0b0011);

    LCD_Write_Quartet(0b0010);

    // Function Set
    LCD_Command(LCD_COMMAND_FUNCTION_SET);

    // Display Off
    LCD_Command(LCD_COMMAND_DISPLAY_OFF);

    // Display Clear
    LCD_Command(LCD_COMMAND_DISPLAY_CLEAR);

    // Entry mode set
    LCD_Command(LCD_COMMAND_ENTRY_MODE_SET);

    // Display On
    LCD_Command(LCD_COMMAND_DISPLAY_ON);

    LCD_RS = LCD_MODE_DATA; // mode donnee
}
