//---------------------------------------------------------
// Sous programme LCD_Write_Quartet
// Auteur: Rolle Clement
// Desc.: sous programme d'ecriture d'un quartet sur le lcd
// Ver. Date: V00 20231222 Cr�ation (YYYYMMDD)	
// Ver. Date: V01 20250520 Modifications
//---------------------------------------------------------

void LCD_Write_Quartet(uint8_t data)
{
    // variables temporaires port et donnee
    uint8_t tempPort;
    uint8_t tempData = 0;

    data = data & 0x0F; // garde les 4 premier bits

    // echange des bits 
    if (data & 0x01)
    {
        tempData |= 0x08; // b0 -> b3 
    }

    if (data & 0x02)
    {
        tempData |= 0x04; // b1 -> b2 
    }

    if (data & 0x04)
    {
        tempData |= 0x02; // b2 -> b1 
    }

    if (data & 0x08)
    {
        tempData |= 0x01; // b3 -> b0 
    }

    tempPort = LCD_DATA_R & 0xF0; // garde sur le port les quatre dernier bits

    tempPort = tempPort | tempData; // rajoute les 4 premiers bit sur le port
    LCD_DATA_W = tempPort; // envoie sur le port

    __delay_us(1);
    LCD_E = LCD_HIGH;
    __delay_us(1); // > 400ns
    LCD_E = LCD_LOW;
    __delay_us(1);
}
