//---------------------------------------------------------
// Sous programme LCD_Cursor_position
// Auteur: Rolle Clement
// Desc.: sous programme pour deplacer le curseur
// Ver. Date: V00 20231222 Cr�ation (YYYYMMDD)	
//---------------------------------------------------------

void LCD_Cursor_Position(uint8_t ligne, uint8_t colonne)
{
    LCD_Command(LCD_COMMAND_FUNCTION_SET);

    LCD_RS = LCD_MODE_CMD; // mode commmande

    uint8_t position_curseur = 0x80; // R/W

    if (ligne == 2)
    {
        position_curseur += 0x40; // position deuxieme ligne 
    }

    position_curseur += (colonne - 1); // premier case = 1 pas 0

    LCD_Write_Char(position_curseur);

    LCD_RS = LCD_MODE_DATA; // mode donnee
}
