//---------------------------------------------------------
// Sous programme LCD_Command
// Auteur: RolleC
// Desc.: sous programme de command du lcd
// Ver. Date: V00 20231222 Cr�ation (YYYYMMDD)	
//---------------------------------------------------------

void LCD_Command(uint8_t commande)
{
    LCD_RS = LCD_MODE_CMD; // mode instruction

    LCD_Write_Quartet(commande >> 4);
    LCD_Write_Quartet(commande);

    __delay_us(50);

    if (commande == LCD_COMMAND_DISPLAY_CLEAR)
    {
        __delay_ms(2);
    }

    LCD_RS = LCD_MODE_DATA; // mode donnee
}
